const lobPolicies = {
    fire: {
        description: "Fire Insurance protects businesses and property owners against losses caused by fire and allied perils. Governed by IRDAI regulations, it covers buildings, machinery, stock, and other assets. ICICI Lombard offers multiple fire products ranging from basic SFSP to comprehensive Industrial All Risk policies.",
        policies: [
            { code: "SFSP", name: "Standard Fire & Special Perils Policy", description: "The foundational property insurance in India. Covers named perils: Fire, Lightning, Explosion/Implosion, Aircraft Damage, Riot/Strike/Malicious Damage, Storm/Tempest/Flood/Inundation (STFI), Impact Damage, Subsidence/Landslide, Bursting of Water Tanks/Pipes, Missile Testing, Leakage from Sprinklers, and Bush Fire. Property covered includes Building (incl. plinth & foundation), Plant & Machinery, Stocks (Raw Material, WIP, Finished Goods), Furniture/Fixtures/Fittings, and other contents. Sum Insured basis: Market Value or Reinstatement Value." },
            { code: "IAR", name: "Industrial All Risk Policy", description: "Broader than SFSP — covers ALL risks of physical loss or damage unless specifically excluded. Suitable for large industrial complexes (Sum Insured typically > ₹50 Crore). Covers accidental damage from any external cause including those not listed in SFSP. Includes automatic covers: Additions/Alterations (15% of SI), Temporary Removal of Stocks (10%), Professional Fees, Debris Removal. Fewer exclusions than SFSP." },
            { code: "FIRE-BI", name: "Business Interruption (Consequential Loss)", description: "Covers loss of Gross Profit and Increased Cost of Working due to interruption of business following material damage by an insured peril. Key elements: Indemnity Period (12/18/24/36 months), Turnover-based sum insured, Rate of Gross Profit calculation. MUST have underlying material damage policy (SFSP or IAR). Also covers Wages, Auditor's Fees, and additional expenses to minimize loss." },
            { code: "FLP", name: "Floater Policy (Declaration Basis)", description: "Single policy covering stocks across multiple named locations with one consolidated sum insured. Insured declares stock values monthly/quarterly; premium adjusted at year-end. Ideal for businesses with fluctuating inventory across warehouses. Reduces administration vs individual policies per location. Average clause applies on overall basis." },
            { code: "BSUS", name: "Bharat Sookshma Udyam Suraksha (Micro Enterprise)", description: "IRDAI-mandated package policy for micro enterprises (investment up to ₹1 Crore). Bundled cover: Fire + Burglary + Money Insurance + Personal Accident + Fidelity Guarantee + Plate Glass + Electronic Equipment. Single policy, simplified underwriting, affordable premium." },
            { code: "BLUS", name: "Bharat Laghu Udyam Suraksha (Small Enterprise)", description: "For small enterprises (investment ₹1-10 Crore). Modular package: Fire (SFSP basis) + optional Burglary + BI + Money Insurance + PA + Machinery Breakdown + EEI. Flexible — choose covers relevant to your business. Standard rating with volume discounts." }
        ],
        addons: [
            { code: "ARCHFEES", name: "Architects, Surveyors & Consulting Engineers Fees", description: "Covers professional fees (typically 3-7.5% of claim amount) for architects, surveyors, and consulting engineers required to supervise rebuilding/reinstatement of damaged property. These fees are over and above the material damage claim.", whoShouldTake: "Any insured with large or complex properties — factories, multi-storey buildings, specialized structures requiring professional supervision for reconstruction.", whyItsNeeded: "Rebuilding after major damage always requires professional oversight. Without this add-on, these mandatory professional fees come from your own pocket, adding 3-7.5% to your effective loss.", claimImpact: "Without it: architect/engineer fees needed for reconstruction planning and supervision are entirely excluded from the claim. Insured bears 3-7.5% additional cost on top of the loss." },
            { code: "DEBRIS", name: "Debris Removal", description: "Covers the actual cost of clearing wreckage and debris before reconstruction can begin. Standard SFSP provides only 1% of claim amount for debris removal; this add-on extends coverage to actual costs incurred.", whoShouldTake: "Multi-storey buildings, industrial units, factories with heavy machinery, chemical plants — any property where debris removal is expensive.", whyItsNeeded: "After a major fire or collapse, debris removal can cost 5-15% of the total loss. The standard 1% allowance is grossly inadequate for most industrial or commercial properties.", claimImpact: "Without it: only 1% of the claim amount is allowed for debris removal. If actual debris clearing costs ₹15 Lakhs on a ₹1 Crore claim, you receive only ₹1 Lakh — bearing ₹14 Lakhs yourself." },
            { code: "DEMOLITION", name: "Demolition & Dismantling Costs", description: "Covers the cost of pulling down undamaged portions of a structure when mandated by municipal or statutory authorities after partial damage. Includes dismantling costs and shoring up expenses.", whoShouldTake: "Owners of old buildings, multi-storey structures, properties in municipal areas where local authorities can mandate demolition of structurally compromised sections.", whyItsNeeded: "After partial damage, municipalities often order demolition of remaining undamaged portions deemed unsafe. This is a significant cost that falls outside normal 'damage' coverage.", claimImpact: "Without it: if municipality orders demolition of undamaged portions after partial fire damage, the entire demolition cost is excluded from the claim. Insured pays to demolish their own undamaged property." },
            { code: "SPCOMB", name: "Spontaneous Combustion", description: "Covers loss or damage caused by self-ignition, spontaneous fermentation, or heating of stocks. Standard SFSP specifically excludes fire caused by the inherent nature of goods (self-heating). Covers coal, cotton, jute, oil seeds, chemicals, and similar commodities.", whoShouldTake: "Coal yards, cotton/jute warehouses, oil seed storage, chemical manufacturers, fertilizer godowns, agricultural commodity traders — anyone storing materials prone to self-heating.", whyItsNeeded: "Many commodities (coal, cotton, jute, oil seeds) are scientifically prone to spontaneous combustion. Standard SFSP excludes this as an 'inherent vice' — leaving a massive gap for commodity-based businesses.", claimImpact: "Without it: any claim arising from self-heating or spontaneous ignition of stocks is REJECTED outright. The entire loss is excluded regardless of quantum. This is one of the most common claim rejections in commodity warehouses." },
            { code: "FOREST", name: "Forest Fire / Jungle Fire", description: "Covers damage from fire spreading from nearby forests or jungles to the insured property. Standard SFSP covers 'bush fire' but specifically excludes forest fire. Critical for properties located near forested zones.", whoShouldTake: "Industrial units, resorts, warehouses, plantations, and any property located within 5-10 km of forest areas, particularly in central and southern India.", whyItsNeeded: "Forest fires are increasing in India due to climate change. Properties near forest zones face real risk, but standard SFSP only covers 'bush fire' — forest fire is a specific exclusion.", claimImpact: "Without it: if fire spreads from a nearby forest and damages your property, the entire claim is excluded. Even if the property is engulfed, the 'forest fire' exclusion denies the claim completely." },
            { code: "IMPACT-OWN", name: "Impact Damage by Own Vehicles", description: "Extends impact damage cover to include damage caused by the insured's own vehicles — forklifts, trucks, cranes, trailers operating within the premises. Standard SFSP only covers impact from third-party vehicles.", whoShouldTake: "Factories, warehouses, logistics hubs, ports, and any premises with internal vehicle movement — forklifts, material handling equipment, delivery trucks, cranes.", whyItsNeeded: "In busy industrial premises, damage from own forklifts and trucks hitting walls, pillars, stored goods, or machinery is common. Standard policy only covers impact from outsider vehicles.", claimImpact: "Without it: damage caused by your own forklift hitting a wall, your truck backing into stored goods, or your crane striking a structure is entirely excluded. Only impact from third-party vehicles is covered." },
            { code: "EQ-FS", name: "Earthquake (Fire & Shock)", description: "Covers both structural/shock damage from seismic events AND fire following earthquake. Zone-based rating from Zone II to Zone V. Includes collapse, cracking, foundation damage, and fire triggered by seismic activity. Deductible typically 5% of claim.", whoShouldTake: "ALL property owners in India, especially those in Zone III-V (most of India). Mandatory consideration for any property with significant asset value.", whyItsNeeded: "India sits on active seismic zones. Without this add-on, ALL earthquake-related damage — whether structural collapse or fire from ruptured gas lines — is completely excluded from the policy.", claimImpact: "Without it: if an earthquake damages your building (cracks, collapse, foundation shift) or triggers a fire, the ENTIRE claim is rejected. Zero payout regardless of loss severity." },
            { code: "EQ-FO", name: "Earthquake (Fire Only)", description: "Covers only fire resulting from earthquake — not structural or shock damage. A cheaper alternative to Fire & Shock variant. Suitable for earthquake-resistant buildings where structural risk is low but fire risk from seismic events remains.", whoShouldTake: "Owners of newer earthquake-resistant structures (built to seismic codes) where structural collapse risk is low but fire from gas leaks or electrical short circuits during earthquake remains a concern.", whyItsNeeded: "Even earthquake-resistant buildings can suffer fires from ruptured gas lines, electrical faults, or chemical spills triggered by tremors. This covers the fire risk at lower premium than full EQ cover.", claimImpact: "Without it: fire originating from an earthquake event is excluded. Even if your building survives structurally, any fire damage triggered by the seismic event gets no payout." },
            { code: "STFI", name: "Storm, Tempest, Flood, Inundation", description: "Covers damage from cyclone, typhoon, hurricane, tornado, flood, and inundation. Essential monsoon cover for Indian properties. Includes damage from storm surge, rising water levels, and windstorm. Excess typically 1-5% of claim.", whoShouldTake: "Virtually every property owner in India — monsoons affect most regions. Critical for coastal properties, riverine locations, low-lying areas, and properties in cyclone-prone zones.", whyItsNeeded: "India experiences severe monsoons, cyclones (Amphan, Tauktae, Biparjoy), and urban flooding annually. Without STFI, all water and wind damage from these events is excluded.", claimImpact: "Without it: ALL flood, storm, cyclone, and inundation damage is excluded. Your factory flooded in monsoon? Zero claim. Roof blown off in cyclone? Zero claim. This is the single most common add-on gap." },
            { code: "TER", name: "Terrorism Cover", description: "Covers property damage from acts of terrorism, provided through the Indian Market Terrorism Risk Insurance Pool backed by GIC Re. Separate premium structure. Covers damage to building, machinery, stocks from declared terrorist acts.", whoShouldTake: "All commercial and industrial properties, especially those in metro cities, near high-value targets, government buildings, or in areas with history of civil unrest. Practically essential for any urban commercial property.", whyItsNeeded: "Post-26/11 Mumbai attacks, terrorism risk is real for Indian businesses. Without this add-on, any damage from a terrorist act — even collateral damage from a nearby attack — is fully excluded.", claimImpact: "Without it: if a terrorist attack damages your property (bomb blast, arson, or even collateral damage from an attack on a nearby target), the ENTIRE claim is rejected. Full exclusion applies." },
            { code: "COLDSTORE", name: "Deterioration of Stocks in Cold Storage", description: "Covers spoilage and deterioration of perishable stocks in cold storage due to temperature change from accidental failure of the refrigeration system. Does NOT cover mechanical breakdown of the refrigeration unit itself (that needs MBD).", whoShouldTake: "Pharma companies, food processors, dairy plants, frozen food distributors, vaccine storage facilities, cold chain logistics operators, restaurants with large cold rooms.", whyItsNeeded: "Perishable stock value often exceeds the cold storage equipment value. A fridge failure can destroy stocks worth crores in hours. Standard fire policy covers fire damage to goods but not spoilage from temperature failure.", claimImpact: "Without it: if your cold storage fails and ₹2 Crore worth of pharma products or perishable food spoils, the entire loss is excluded. The policy only covers fire/flood damage to stocks, not temperature-related deterioration." },
            { code: "LEAKCONTAM", name: "Leakage & Contamination Cover", description: "Covers accidental leakage from storage tanks, pipelines, or containers that contaminates or damages other insured property or stocks. Includes chemical spills, liquid leakage, and cross-contamination events.", whoShouldTake: "Chemical manufacturers, petroleum storage, pharma plants, food processing units, paint manufacturers, any business with bulk liquid storage tanks or pipeline systems.", whyItsNeeded: "Accidental leaks from tanks and pipelines can contaminate adjacent stocks worth far more than the leaked material itself. Standard fire policy does not cover gradual or sudden leakage as a peril.", claimImpact: "Without it: if a chemical tank leaks and contaminates adjacent raw materials or finished goods, the contamination damage is excluded. Only direct fire/explosion damage is covered — not leakage-induced losses." },
            { code: "OMISSION", name: "Omission to Insure (Additions/Alterations/Extensions)", description: "Provides automatic cover for new assets acquired, erected, or installed during the policy period that were not declared at inception. Typically covers up to 15% of existing sum insured for that category (excluding stocks).", whoShouldTake: "Growing businesses that regularly acquire new machinery, expand premises, or add capital assets during the year. Particularly important for manufacturing units undergoing modernization.", whyItsNeeded: "Businesses acquire new assets throughout the year. Without this clause, any new machinery or building extension added mid-term has ZERO coverage until formally endorsed — creating dangerous gaps.", claimImpact: "Without it: newly acquired assets are completely uninsured until the next renewal or formal endorsement. If a new machine worth ₹50 Lakhs (bought 2 months ago) is damaged by fire, zero payout — it was never declared." },
            { code: "TEMPREM", name: "Temporary Removal of Stocks", description: "Covers stocks temporarily removed from the insured premises to other locations for processing, job-work, fabrication, or finishing. Standard limit is 10% of stock sum insured. Coverage applies while stocks are at the third-party location.", whoShouldTake: "Manufacturers who send raw materials or semi-finished goods to third parties for job-work, surface treatment, testing, or specialized processing.", whyItsNeeded: "Manufacturing supply chains involve frequent movement of materials to external processors. Stocks at a third-party location are outside the policy's declared premises — creating a coverage gap.", claimImpact: "Without it: stocks sent for job-work or processing at another location have ZERO coverage. If a fire at the job-worker's premises destroys your ₹30 Lakhs of material, you get nothing — it was outside declared premises." },
            { code: "LOSSRENT", name: "Loss of Rent", description: "Covers rental income lost by the landlord when insured property is damaged by an insured peril and becomes uninhabitable/unusable by tenants. Indemnity period typically 3-12 months until property is restored to lettable condition.", whoShouldTake: "Commercial and residential landlords, real estate investors, property owners with tenanted buildings — anyone deriving rental income from insured property.", whyItsNeeded: "Rent loss is a pure financial/consequential loss, not physical damage. Standard fire policy covers property repair but not the income stream you lose while the property is being rebuilt.", claimImpact: "Without it: while your damaged building is being repaired (3-12 months), the entire rental income you lose is from your own pocket. The policy pays to fix the building but not the lost rent during repair period." },
            { code: "RENTALT", name: "Rent for Alternative Accommodation", description: "Covers additional rent paid by the insured (tenant/occupier) for temporary alternative premises when their own insured premises become uninhabitable due to insured damage. Covers the rent differential for temporary space.", whoShouldTake: "Business occupiers (tenants) of commercial/industrial premises, office occupants, shop owners operating from rented premises who would need alternative space if displaced.", whyItsNeeded: "When your office or shop is damaged, you must find alternative premises to continue operations. The additional rent for temporary space is not covered under standard property repair.", claimImpact: "Without it: if your office/factory is gutted and you must rent alternative premises for 6 months at ₹3 Lakhs/month while repairs happen, you bear the entire ₹18 Lakhs alternative rent cost yourself." },
            { code: "ARCHFEES-ALT", name: "Architects & Surveyors Fees (Higher Limit)", description: "Provides a higher percentage (up to 10%) for professional fees compared to the standard 3% cap. Designed for specialized properties requiring complex architectural or engineering supervision during reconstruction.", whoShouldTake: "Heritage buildings, specialized industrial structures, hospitals, data centers, cleanrooms, and any property requiring specialized architectural or engineering expertise for restoration.", whyItsNeeded: "Standard architect fees cover of 3% is inadequate for complex properties. Heritage restoration, hospital rebuilding, or cleanroom reconstruction requires specialist professionals charging premium fees.", claimImpact: "Without it: professional fees are capped at standard 3% (or basic ARCHFEES limit). For specialized properties where actual architect/consultant fees are 8-10% of claim, the excess is from own pocket." },
            { code: "STARTUP", name: "Start-up Expenses", description: "Covers additional one-time costs incurred to restart business operations after an insured loss — including cleaning, decontamination, testing, recalibration of equipment, trial runs, and safety certifications required before resuming production.", whoShouldTake: "Manufacturing units, process industries, chemical plants, food processing facilities — any business requiring testing, recalibration, or safety clearance before resuming operations after damage.", whyItsNeeded: "After fire damage, you cannot simply repair and restart. Equipment needs recalibration, premises need decontamination, safety inspections are mandatory. These costs are separate from repair costs.", claimImpact: "Without it: all restart costs beyond physical repair — cleaning, testing, recalibration, trial runs, safety re-certification — are excluded from the claim. Insured bears these as additional out-of-pocket expenses." },
            { code: "ESCALATION", name: "Escalation Clause / Inflation Protection", description: "Automatically increases sum insured by 10-25% during the policy year to account for inflation in construction costs, material prices, and labor charges. Prevents underinsurance from rising prices triggering the Average Clause at claim time.", whoShouldTake: "All property owners, especially those with Reinstatement Value policies where the gap between declared SI and actual replacement cost widens with inflation.", whyItsNeeded: "Construction and material costs rise 8-15% annually in India. A sum insured adequate at policy start can be 10-15% underinsured by year-end — triggering proportionate claim reduction under Average Clause.", claimImpact: "Without it: if construction costs rise 12% during the year and your SI does not keep pace, you are technically underinsured. Average Clause applies at claim — reducing your payout proportionately. A ₹1 Crore claim could be cut to ₹85 Lakhs." },
            { code: "INVOL-BETTER", name: "Involuntary Betterment", description: "Covers unavoidable improvement costs when exact replacement of damaged property is not available in the market. When old materials, machinery, or components are discontinued, the insured is forced to buy newer (better) versions.", whoShouldTake: "Owners of older buildings (10+ years), factories with legacy machinery, properties with discontinued materials (specific tiles, fittings, or components no longer manufactured).", whyItsNeeded: "Insurance pays for like-for-like replacement. But if your 15-year-old machine or specific building material is discontinued, you MUST buy a newer version — and the insurer deducts the 'improvement' value.", claimImpact: "Without it: insurer deducts 'betterment' value from the claim when replacement is newer/better than original. If your old ₹20 Lakh machine is replaced by a ₹25 Lakh current model, insurer may pay only ₹20 Lakhs — you bear ₹5 Lakhs." },
            { code: "WAIVER-BETTER", name: "Waiver of Betterment", description: "Eliminates the deduction for betterment when repair or replacement results in the property being in a better condition than before the loss. Insurer agrees not to apply new-for-old deductions up to a specified limit (typically 15-20%).", whoShouldTake: "Owners of older properties and machinery (particularly 10+ years old) where ANY repair will inevitably involve newer materials/components that constitute 'betterment'.", whyItsNeeded: "In practice, almost every repair involves some betterment — new paint on old walls, new parts in old machines, new tiles replacing worn ones. Without waiver, insurer reduces every claim for this 'improvement'.", claimImpact: "Without it: insurer deducts betterment from every claim where repairs make property 'better' than pre-loss condition. New paint, new components, better materials — all attract deductions of 10-30% from the claim." },
            { code: "DESIG-PROP", name: "Designation of Property", description: "Removes the distinction between buildings and contents for claim allocation purposes. Total sum insured across all categories is treated as one pool. Prevents disputes about which specific item was damaged and under which category.", whoShouldTake: "Businesses with complex premises where building fixtures, machinery, and contents are intermingled — hotels, hospitals, shopping malls, factories with integrated systems.", whyItsNeeded: "Standard policies require damage to be allocated to specific categories (building vs machinery vs stock). Disputes arise when items fall between categories or are incorrectly classified.", claimImpact: "Without it: if a damaged item cannot be specifically identified under the correct sum insured category, or is classified under an exhausted sub-limit, the claim for that item is denied or reduced." },
            { code: "LOSS-MIN", name: "Loss Minimisation Expenses", description: "Covers reasonable costs incurred by the insured to prevent or minimize an imminent insured loss — such as emergency actions during a fire, flood prevention measures, or temporary protections during a storm.", whoShouldTake: "All property owners, particularly those in flood-prone areas or with high-value exposed assets where emergency protective action can save significant losses.", whyItsNeeded: "During an emergency (approaching flood, spreading fire), spending money on sandbagging, emergency firefighting, or temporary covers can save the property. But these expenses are not 'damage' covered by standard policy.", claimImpact: "Without it: money spent on emergency measures to save your property — sandbags during flood, private fire brigades, emergency pumping, temporary covers — is entirely from own pocket, even if it saved lakhs in damage." },
            { code: "EXPEDITE", name: "Expediting Expenses", description: "Covers additional costs of overtime labor, express freight, air shipping, and premium charges to speed up repairs and replacement after an insured loss. Standard policy only covers normal-pace repair costs.", whoShouldTake: "Manufacturing units where production downtime costs more than expedited repair, businesses with time-sensitive operations, seasonal businesses needing quick restoration.", whyItsNeeded: "Normal repair timelines can mean weeks of lost production. Paying overtime or air-freighting parts dramatically cuts downtime — but standard policy only reimburses normal-cost repairs.", claimImpact: "Without it: insurer only pays for repairs at normal speed and cost. If you air-freight a ₹5 Lakh part (vs ₹50K sea freight) to save 4 weeks of production loss, you bear the ₹4.5 Lakh air freight difference yourself." },
            { code: "PAIRS-SETS", name: "Pairs & Sets Clause", description: "When one item of a pair or set is damaged, pays the proportionate value of the complete set rather than just the individual damaged item. Recognizes that a broken set has reduced overall value.", whoShouldTake: "Hotels, retail showrooms, furnished offices, interior designers, and businesses with matched furniture, equipment sets, or paired items where value depends on completeness.", whyItsNeeded: "A damaged item from a matched set (one chair from a set of 8, one earring from a pair) reduces the value of the entire set, not just the single item. Standard policy pays only for the damaged piece.", claimImpact: "Without it: only the individual damaged item's value is paid. If one chair from a ₹8 Lakh designer set of 8 is destroyed, you get ₹1 Lakh (one chair) — but the remaining 7 unmatched chairs lose significant value too." },
            { code: "BRANDS", name: "Brands & Trademarks Clause", description: "Requires that damaged branded goods have all brand labels, trademarks, and identifying marks removed before salvage disposal. Protects the insured's brand reputation from damaged goods re-entering the market.", whoShouldTake: "Brand owners, FMCG companies, premium product manufacturers, luxury goods companies, pharma firms — any business where brand reputation has significant commercial value.", whyItsNeeded: "After a fire or flood, partially damaged branded goods are sold as salvage. Without this clause, your premium brand products (in damaged condition) can be sold in open market with your label — destroying brand value.", claimImpact: "Without it: salvaged goods with your brand name can be sold as-is in the market. Damaged or substandard products bearing your trademark reach consumers — causing reputation damage worth far more than the claim itself." },
            { code: "ADDL-CUSTOMS", name: "Additional Customs Duty", description: "Covers extra import/customs duty payable when replacement parts or machinery must be imported after an insured loss. Includes duty differential between original import (possibly at concessional rate) and current replacement import.", whoShouldTake: "Businesses with imported machinery, CNC equipment, medical devices, specialized industrial equipment, or any assets where replacements must be sourced internationally.", whyItsNeeded: "When imported machinery is damaged, replacement parts attract current customs duty (often 20-40%). Original equipment may have been imported at concessional rates under EPCG or SEZ schemes — replacement attracts full duty.", claimImpact: "Without it: customs duty on replacement imports is excluded from the claim. If a ₹50 Lakh imported part attracts ₹15 Lakhs customs duty, you bear the entire duty cost yourself — insurer pays only the part's base value." },
            { code: "CLAIMS-PREP", name: "Claims Preparation Costs", description: "Covers professional fees for accountants, loss assessors, and documentation experts engaged by the insured to prepare, compile, and substantiate the insurance claim. Typically covers 1-3% of claim amount.", whoShouldTake: "All businesses, especially those with complex assets, multi-location risks, or large potential claims where professional claim preparation significantly improves settlement outcomes.", whyItsNeeded: "Large claims require professional preparation — stock reconciliation, asset valuation, loss quantification, document compilation. Without professional help, claims are often under-settled by 20-40%.", claimImpact: "Without it: all costs of proving your claim (chartered accountant fees, documentation, stock reconciliation, asset valuation by professionals) are entirely from own pocket. You pay to prove your own loss." },
            { code: "AUTO-REINST", name: "Automatic Reinstatement of Sum Insured", description: "After a partial claim is paid, the sum insured is automatically restored to its original full amount without requiring formal endorsement. Additional pro-rata premium is charged for the reinstated amount.", whoShouldTake: "All property owners, especially those in areas prone to multiple events (monsoon flooding followed by cyclone) or with high-value concentrated assets where any SI reduction creates vulnerability.", whyItsNeeded: "After a claim, the remaining sum insured reduces by the claim amount. Without reinstatement, you are underinsured for the rest of the year — vulnerable to a second event with insufficient cover.", claimImpact: "Without it: after a ₹50 Lakh claim on a ₹2 Crore policy, remaining SI drops to ₹1.5 Crore. If a second event occurs causing ₹1.8 Crore damage, maximum payout is only ₹1.5 Crore — you bear ₹30 Lakhs shortfall." },
            { code: "CAP-ADDITIONS", name: "Capital Additions", description: "Covers new capital assets (buildings, machinery, equipment) acquired during the policy period beyond the standard Omission to Insure clause. Provides higher limits (25-50% of SI) for major new acquisitions and expansions.", whoShouldTake: "Rapidly growing businesses, companies executing expansion plans, manufacturers commissioning new production lines, or businesses undergoing significant capital expenditure during the policy year.", whyItsNeeded: "The standard Omission clause covers only 15% of SI. Major expansions (new factory wing, large machine) can exceed this threshold — leaving significant new assets completely uninsured.", claimImpact: "Without it: new capital assets exceeding the 15% Omission threshold have ZERO coverage until formal endorsement. A new ₹5 Crore production line installed mid-year could be completely uninsured if above the threshold." },
            { code: "CONTRACT-PRICE", name: "Contract Price Clause (Stocks)", description: "For finished goods already sold but awaiting delivery, covers the contract selling price (including profit margin) rather than just the manufacturing cost price. Recognizes that sold goods represent committed revenue.", whoShouldTake: "Manufacturers with significant finished goods inventory already sold on contract, exporters with confirmed orders, businesses with long order-to-delivery cycles.", whyItsNeeded: "Standard policy covers stock at cost price or market value. But goods already sold on contract represent committed revenue at selling price. Losing them means losing the profit margin too.", claimImpact: "Without it: for goods already sold at ₹100 but costing ₹70 to manufacture, insurer pays only ₹70 (cost price). You lose ₹30/unit profit margin on goods you were contractually obligated to deliver. Customer claims may follow." },
            { code: "SPOILAGE-MD", name: "Spoilage / Material Damage Extension", description: "Covers raw materials, work-in-progress, or finished goods spoiled due to contamination arising from an insured event — smoke damage, water contamination from firefighting, chemical cross-contamination after explosion.", whoShouldTake: "Food processors, pharma manufacturers, chemical companies, textile mills, electronics manufacturers — any business where goods can be rendered unusable by smoke, water, or contamination from an insured event.", whyItsNeeded: "Fire damage is obvious. But smoke and water from firefighting can contaminate adjacent undamaged stocks — rendering them worthless. Standard policy may only cover directly burned goods, not those spoiled by proximity.", claimImpact: "Without it: only directly damaged goods are covered. Stocks spoiled by smoke contamination, water damage from firefighting, or chemical cross-contamination may be excluded — even though they are rendered commercially worthless." },
            { code: "PROF-ASSESS", name: "Professional Fees for Claim Assessment", description: "Covers fees of independent surveyors, loss assessors, and valuation experts engaged to quantify and verify the actual loss amount. Different from Claims Preparation — this covers the assessment/quantification of loss itself.", whoShouldTake: "Businesses with complex assets requiring specialist valuation — machinery, specialized equipment, unique properties, or scenarios where standard surveyors lack domain expertise.", whyItsNeeded: "Complex losses (specialized machinery, unique processes) require expert assessment to establish true loss quantum. Without specialist input, standard surveyor assessment may significantly undervalue the claim.", claimImpact: "Without it: fees for independent loss quantification experts and specialist surveyors are self-funded. If you engage a machinery expert at ₹3 Lakhs to prove your ₹1 Crore machine is actually a total loss (not repairable), you bear that fee." },
            { code: "VAL-DOCS", name: "Valuable Documents & Records", description: "Covers the cost of reconstructing, replacing, or reproducing important business documents, records, drawings, and data destroyed by an insured peril. Includes engineering drawings, legal documents, accounting records, and design files.", whoShouldTake: "Architects, engineering firms, law offices, R&D companies, manufacturers with proprietary designs, businesses with critical paper records not fully digitized.", whyItsNeeded: "Destroyed business records, proprietary drawings, legal documents, and design files can cost significant sums to reconstruct — engaging professionals, repeating surveys, recreating years of work.", claimImpact: "Without it: cost of recreating destroyed records, redrawing engineering plans, reconstructing legal files, or reproducing R&D documentation is entirely excluded. Physical paper/media damage may be covered but not the intellectual reconstruction cost." },
            { code: "ELEC-INSTALL", name: "Electrical Installations (All Perils)", description: "Extends fire cover to include damage to electrical installations from all causes including electrical faults, short circuits, overloading, and power surges that cause fire or damage. Covers wiring, panels, transformers, and switchgear.", whoShouldTake: "All commercial and industrial property owners, especially those with extensive electrical infrastructure — factories, IT buildings, data centers, hospitals, shopping malls.", whyItsNeeded: "Fire originating from electrical faults is technically covered, but damage TO electrical installations from internal electrical causes (short circuit, surge) can face coverage disputes under standard SFSP.", claimImpact: "Without it: while fire FROM electrical fault is covered, damage TO electrical installations themselves from internal electrical causes may face claim disputes. Burnt transformers, melted panels, damaged wiring from electrical surge may not be fully covered." }
        ]
    },
    liability: {
        description: "Liability Insurance protects businesses, professionals, and directors against legal claims arising from bodily injury, property damage, financial loss, or negligence caused to third parties. With India's evolving regulatory landscape — Consumer Protection Act 2019, DPDP Act 2023, Companies Act 2013, SEBI regulations, and active consumer courts — liability insurance has become essential for every business operating in India.",
        policies: [
            { code: "PL", name: "Public Liability Insurance", description: "Covers legal liability for accidental bodily injury or property damage to third parties arising from the insured's business operations or premises. MANDATORY under Public Liability Insurance Act 1991 for industries handling hazardous substances. Occurrence-based trigger. Covers: visitor injuries on premises, damage from operations to neighboring property, pollution liability (sudden & accidental). Third-party liability for death/injury is unlimited in India under certain statutes. Premium based on turnover, nature of operations, and number of employees." },
            { code: "D&O", name: "Directors & Officers Liability (D&O)", description: "Protects directors and senior officers against personal liability for wrongful acts committed in their managerial capacity. Claims-made basis with retroactive date. Structure: Side A (directors when company can't indemnify — insolvency), Side B (reimburses company for indemnifying directors), Side C (entity cover for securities claims). Covers: shareholder derivative actions, regulatory investigations (SEBI, RBI, MCA, NCLT), employment practices claims, insolvency proceedings, breach of fiduciary duty. Defense costs typically WITHIN limit (erodes indemnity). Essential for listed companies, PE/VC-backed startups, and any company with independent directors." },
            { code: "CGL", name: "Commercial General Liability (CGL)", description: "The broadest general liability cover available — covers bodily injury, property damage, personal injury, and advertising injury across all business operations. Coverage parts: Premises Liability (slip & fall, visitor injuries), Operations Liability (damage caused by work at other locations), Products/Completed Operations (injury from products after sale or work after completion), Personal & Advertising Injury (defamation, copyright infringement, malicious prosecution). Occurrence-based trigger. Defense costs typically IN ADDITION to limit (does not erode indemnity). Per-occurrence limit + annual aggregate. The go-to liability policy for comprehensive business protection." },
            { code: "PROD", name: "Product Liability Insurance", description: "Covers legal liability for bodily injury or property damage caused by defective products manufactured, sold, distributed, or supplied by the insured. Consumer Protection Act 2019 imposes STRICT LIABILITY — consumer need not prove negligence, only that the product was defective. Three types of defects: Manufacturing (production error), Design (inherently unsafe design), Warning (inadequate instructions/labels). Covers manufacturers, distributors, retailers, importers. Product recall costs usually require separate sub-limit or standalone policy. Critical for pharma, auto parts, electronics, food, consumer goods, and exporters to USA/EU." },
            { code: "PI", name: "Professional Indemnity (PI / E&O)", description: "Covers professionals against claims of negligence, errors, omissions, or breach of professional duty in services rendered to clients. Claims-made basis with retroactive date. Covers: incorrect professional advice, design errors (architects/engineers), misdiagnosis (doctors), audit failures (CAs), software bugs causing client loss (IT companies), legal malpractice (lawyers). Defense costs typically WITHIN limit. Run-off/discovery period extension critical when changing insurers or retiring. Essential for: IT/ITES, doctors/hospitals, CAs/CS, lawyers, architects, management consultants, insurance brokers." },
            { code: "CYBER", name: "Cyber Liability Insurance", description: "Covers first-party losses and third-party liability arising from cyber incidents — data breaches, network security failures, ransomware, and privacy violations. First-party covers: breach response costs (forensics, notification, credit monitoring), data restoration, business interruption from network outage, cyber extortion/ransomware payments, reputation management/PR. Third-party covers: claims from affected data subjects, regulatory fines (DPDP Act 2023 — up to ₹250 Crore), PCI-DSS fines, media liability. DPDP Act mandates 72-hour breach notification and imposes significant penalties. Claims-made basis. Essential for IT, BFSI, healthcare, e-commerce, any business handling customer PII." },
            { code: "EPL", name: "Employment Practices Liability (EPL)", description: "Covers claims from employees alleging wrongful employment practices — discrimination (gender, age, caste, religion), sexual harassment (POSH Act 2013), wrongful termination, retaliation, breach of employment contract, failure to promote, workplace bullying. Covers defense costs + settlements/judgments. Claims-made basis. Growing importance in India with active labor courts, POSH compliance requirements, and increasing employee awareness of rights. Covers the company and individual managers/HR heads." },
            { code: "WC", name: "Workmen's Compensation (WC) Policy", description: "Covers employer's legal liability to pay compensation to employees for death or bodily injury arising out of and in the course of employment, under the Workmen's Compensation Act 1923 (now Employee's Compensation Act). Covers: fatal accidents (lump sum to dependents), permanent total/partial disability, temporary disability (half-monthly payments). Compensation calculated based on monthly wages and age of worker. MANDATORY for employers with workers in hazardous occupations. Covers legal fees for defending WC claims." }
        ],
        addons: [
            { code: "DEF-COSTS-ADD", name: "Defense Costs in Addition to Limit", description: "Defense costs (legal fees, court expenses, expert witnesses) are paid IN ADDITION to the policy limit rather than eroding it. Without this, expensive litigation can consume the entire policy limit on legal fees alone, leaving nothing for the actual settlement.", whoShouldTake: "All D&O and PI policyholders. Especially important for directors of listed companies, professionals in high-litigation sectors (healthcare, IT), and any insured facing potentially complex or prolonged legal proceedings.", whyItsNeeded: "Legal defense in India (and cross-border) can cost ₹50L-5Cr+. If defense costs are 'within limit' on a ₹5Cr policy, ₹2Cr in legal fees leaves only ₹3Cr for settlement — potentially insufficient for the actual claim.", claimImpact: "Without it: defense costs ERODE the indemnity limit. On a ₹5 Crore D&O policy with ₹2 Crore legal defense costs, only ₹3 Crore remains for actual settlement/judgment. If judgment exceeds ₹3 Crore, the excess is personal liability." },
            { code: "RETRO-DATE", name: "Retroactive Date Extension / Full Prior Acts", description: "Extends the retroactive date (the earliest date from which past wrongful acts are covered) to inception of the insured's first-ever policy, or removes it entirely ('full prior acts'). Critical for claims-made policies where past acts may surface as claims during current policy.", whoShouldTake: "All D&O, PI, and Cyber policyholders — especially when switching insurers. Companies with long operating history where past decisions/actions could generate future claims.", whyItsNeeded: "Claims-made policies only cover acts occurring AFTER the retroactive date. Without full prior acts coverage, any wrongful act before the retro date is excluded — even if the claim is first made during the current policy period.", claimImpact: "Without it: any claim arising from acts/omissions BEFORE the retroactive date is excluded. If a director's decision from 3 years ago triggers a lawsuit today, and retro date is only 1 year back — ZERO coverage. Full personal liability." },
            { code: "RUN-OFF", name: "Run-off / Discovery Period Extension", description: "Provides continued coverage for a specified period (1-6 years, or unlimited) after a claims-made policy expires or is not renewed. Allows claims to be reported after the policy ends for wrongful acts that occurred during the policy period.", whoShouldTake: "Retiring directors, professionals closing practice, companies undergoing M&A (target company), any insured not renewing their claims-made policy (switching to a new insurer or ceasing operations).", whyItsNeeded: "Claims-made policies provide ZERO coverage after expiry for unreported claims. Without run-off, a director who retires has no protection against future claims arising from decisions made during their tenure.", claimImpact: "Without it: once the policy expires/is not renewed, NO claims can be reported — even for acts during the policy period. A retiring director who faces a lawsuit 2 years after retirement has ZERO coverage. Full personal exposure." },
            { code: "ENTITY-COVER", name: "Entity Coverage (Side C)", description: "Extends D&O coverage to the company itself (not just individual directors) for securities claims, regulatory investigations, and certain specified company-level claims. Without this, only individual directors are protected — the company bears its own liability.", whoShouldTake: "Listed companies (BSE/NSE), companies planning IPO, PE/VC-funded startups with investor agreements, any company facing potential securities litigation or regulatory action at the entity level.", whyItsNeeded: "SEBI actions, shareholder suits, and securities claims often name both the company AND directors. Without entity cover, the company must self-fund its defense and settlement — potentially threatening its solvency.", claimImpact: "Without it: the company itself has NO coverage under the D&O policy. If SEBI imposes a ₹50 Crore penalty on the company (not individual directors), or a class action targets the entity — the company pays entirely from its own balance sheet." },
            { code: "CYBER-EXT", name: "Cyber Extortion / Ransomware Coverage", description: "Covers ransom payments (cryptocurrency or otherwise), negotiation costs, and forensic expenses related to ransomware attacks and cyber extortion demands. Includes costs of engaging specialist negotiators and cryptocurrency facilitators.", whoShouldTake: "All businesses with digital infrastructure — IT companies, BFSI, healthcare, manufacturing with SCADA/OT systems, e-commerce, any business that cannot afford extended downtime from encrypted systems.", whyItsNeeded: "Ransomware attacks in India increased 50%+ in recent years. Average ransom demand: ₹5-50 Lakhs for SMEs, ₹1-10 Crore for large enterprises. Without cover, the business faces paying ransom or extended downtime — both catastrophic.", claimImpact: "Without it: ransomware payment (if business decides to pay), negotiator fees, cryptocurrency purchase costs, and forensic investigation expenses are entirely self-funded. Many businesses face the impossible choice of paying ransom from own funds or losing all data." },
            { code: "RECALL-EXP", name: "Product Recall Expense Coverage", description: "Covers the costs of recalling defective products from the market — notification to consumers, logistics of collection, storage, destruction/disposal of recalled products, replacement costs, and communication/PR expenses. Separate from product liability (which covers injury claims).", whoShouldTake: "Food & beverage manufacturers, pharma companies, auto parts suppliers, consumer electronics makers, toy manufacturers, any business producing goods distributed to mass consumer markets.", whyItsNeeded: "A product recall can cost ₹10-100+ Crore (logistics, replacement, PR) — far exceeding any single injury claim. FSSAI, CDSCO, and consumer courts can mandate recalls. The recall cost itself is NOT covered under standard product liability.", claimImpact: "Without it: ALL recall expenses — notification, retrieval, transportation, storage, destruction, replacement, advertising — are entirely from own pocket. Standard product liability only covers injury claims, NOT the operational cost of removing products from market." },
            { code: "POSH-COVER", name: "POSH Act / Sexual Harassment Coverage", description: "Specific coverage for claims arising under the Prevention of Sexual Harassment at Workplace Act 2013 (POSH Act). Covers defense costs for the company and individuals, compensation ordered by Internal Complaints Committee (ICC), and costs of external investigations.", whoShouldTake: "All companies with 10+ employees (POSH Act applicability threshold). Especially critical for companies with large workforces, multiple offices, or industries with high POSH claim frequency (media, hospitality, IT).", whyItsNeeded: "POSH compliance is mandatory. Claims can result in significant compensation orders, termination disputes, and reputational damage. Companies face liability for both the harassment AND for failing to prevent it or conduct proper inquiry.", claimImpact: "Without it: compensation ordered under POSH Act, legal fees for defending POSH proceedings, costs of external investigations mandated by the committee, and any damages awarded — all from company's own funds." },
            { code: "INSURED-VS-INSURED", name: "Insured vs Insured Exclusion Carve-back", description: "Standard D&O policies exclude claims brought by one insured person against another (e.g., company suing its own director). This carve-back reinstates coverage for specific scenarios — derivative actions, whistleblower claims, insolvency proceedings where liquidator sues directors.", whoShouldTake: "Directors of companies with multiple shareholders (especially PE/VC investors who may sue management), companies in financial distress, and boards with potential internal conflicts of interest.", whyItsNeeded: "In practice, many legitimate D&O claims ARE brought by the company itself (through shareholders, liquidators, or new management). The insured-vs-insured exclusion can negate coverage precisely when directors need it most — during internal disputes or insolvency.", claimImpact: "Without it: if the company (through shareholders, liquidator, or new board) sues a former director for mismanagement, the D&O policy EXCLUDES the claim entirely. Director has zero coverage for potentially the most dangerous type of claim they face." },
            { code: "CRISIS-MGMT", name: "Crisis Management / Reputation Costs", description: "Covers costs of engaging PR consultants, crisis communication specialists, and reputation management firms following a covered event that threatens the insured's public reputation. Includes media monitoring, stakeholder communication, and brand rehabilitation expenses.", whoShouldTake: "Consumer-facing brands, listed companies, professionals with public profiles (doctors, lawyers), and any business where reputational damage from a liability event could exceed the direct claim cost.", whyItsNeeded: "A liability event (product injury, data breach, director scandal) can destroy brand value worth multiples of the direct claim. Proactive crisis management can contain reputational damage — but PR/communication firms charge ₹10-50 Lakhs+ for crisis response.", claimImpact: "Without it: all crisis communication costs — PR firm engagement, media management, stakeholder outreach, brand rehabilitation campaigns — are entirely self-funded. The reputational fallout from poorly managed crises often costs 5-10x the original claim." },
            { code: "MEDIATION", name: "Mediation & ADR Costs", description: "Covers costs of mediation, arbitration, and alternative dispute resolution (ADR) proceedings — including mediator/arbitrator fees, legal representation at ADR, expert witnesses, and venue costs. Encourages early resolution without full litigation.", whoShouldTake: "All liability policyholders, especially those in commercial disputes, professional negligence claims, or employment matters where mediation/arbitration is increasingly mandated by Indian courts.", whyItsNeeded: "Indian courts encourage ADR (mandatory mediation under CPC amendments). ADR is faster and cheaper than litigation, but still involves significant costs — arbitrator fees alone can be ₹5-20 Lakhs for complex disputes.", claimImpact: "Without it: mediator/arbitrator fees, legal costs for ADR proceedings, expert fees, and venue charges are all self-funded. Insureds may avoid beneficial early settlement through mediation because they cannot afford the ADR process costs." },
            { code: "SUBCONTRACTOR", name: "Subcontractor Liability Extension", description: "Extends CGL/PL coverage to include liability arising from the acts of the insured's subcontractors while performing work on the insured's behalf. Without this, the insured may face claims for subcontractor negligence with no policy response.", whoShouldTake: "Construction companies, IT services firms, facility management companies, logistics operators, and any business that routinely engages subcontractors to perform work for clients on their behalf.", whyItsNeeded: "Under Indian law, the principal employer can be held liable for the acts of subcontractors. If a subcontractor causes injury or damage while working on your project, the injured party typically sues the main contractor — not the sub.", claimImpact: "Without it: if your subcontractor's negligence causes third-party injury or property damage while working on your contract, your CGL policy EXCLUDES the claim. You bear full liability for your subcontractor's actions — no coverage." },
            { code: "WORLDWIDE", name: "Worldwide Jurisdiction (excl. USA/Canada)", description: "Extends territorial scope of the liability policy beyond India to cover claims arising anywhere in the world (excluding USA/Canada due to litigious environment). Essential for companies with international operations, exports, or services delivered globally.", whoShouldTake: "Exporters, IT services companies with global clients, manufacturers exporting products, consultants serving international clients, any business with cross-border operations or customer base.", whyItsNeeded: "Standard Indian liability policies cover only India jurisdiction. If your product injures someone in Europe, or your IT service causes loss to a UK client, you need worldwide coverage to respond to claims filed in foreign jurisdictions.", claimImpact: "Without it: claims filed outside India are completely excluded. If your exported product causes injury in Germany, or your IT delivery error causes loss to a Singapore client — ZERO coverage. You face foreign litigation with no insurance support." },
            { code: "USA-CANADA", name: "USA/Canada Jurisdiction Extension", description: "Extends coverage to claims arising in or governed by US/Canadian law — the most expensive and litigious jurisdictions globally. Significantly higher premium due to extreme litigation costs, punitive damages, and class action exposure in these territories.", whoShouldTake: "Indian companies with direct US/Canada exposure — IT services firms with US clients, pharma companies exporting to USA, manufacturers supplying US automotive/aerospace, any company with US subsidiary or significant US revenue.", whyItsNeeded: "US litigation costs are 10-50x India levels. Average product liability verdict in USA exceeds $5 million. Class actions can result in billion-dollar settlements. Without explicit US coverage, any US claim is excluded — leaving potentially unlimited personal exposure.", claimImpact: "Without it: ANY claim originating in USA/Canada or governed by US/Canadian law is excluded. If your software bug causes a US client $10M loss, or your product injures a US consumer — ZERO coverage. US litigation defense alone can cost $1-5M." },
            { code: "PUNITIVE-DMG", name: "Punitive / Exemplary Damages", description: "Covers punitive and exemplary damages awarded by courts to punish the defendant for egregious conduct — over and above compensatory damages. Many standard policies exclude punitive damages. This buy-back reinstates coverage where legally insurable.", whoShouldTake: "Companies facing potential consumer class actions, businesses in sectors with high regulatory scrutiny, exporters to litigious jurisdictions, and any insured where courts may award punitive damages to 'make an example'.", whyItsNeeded: "Indian courts increasingly award punitive damages (consumer courts, NCDRC). In cross-border claims, punitive damages can be 3-10x compensatory damages. Standard policies often exclude these — leaving the most painful part of a judgment uncovered.", claimImpact: "Without it: punitive/exemplary damages awarded by the court are entirely excluded from the policy. If a court awards ₹5 Crore compensatory + ₹15 Crore punitive damages, the policy may only pay ₹5 Crore — you bear ₹15 Crore yourself." },
            { code: "THIRD-PARTY-CYBER", name: "Third-Party Cyber Liability (for non-Cyber policies)", description: "Adds cyber/privacy liability coverage to CGL or PI policies — covering claims arising from data breaches, unauthorized disclosure of third-party data, or failure to protect client information. A lighter alternative to standalone cyber policy.", whoShouldTake: "Professional services firms, consultants, accountants, lawyers, and small businesses that handle client data but don't have a standalone cyber policy and want basic data liability protection.", whyItsNeeded: "Standard CGL/PI policies have broad 'electronic data' exclusions. Any claim involving data loss, privacy breach, or unauthorized disclosure of client information falls outside coverage — a growing risk for all service businesses.", claimImpact: "Without it: if your firm accidentally leaks client financial data, or your system is breached exposing customer PII — standard CGL/PI policy EXCLUDES the claim due to electronic data/cyber exclusions. Zero coverage for what is increasingly the #1 risk for service firms." }
        ]
    },
    engineering: {
        description: "Engineering Insurance covers risks during construction, erection, testing, commissioning, and operation of machinery, equipment, and infrastructure projects. ICICI Lombard provides comprehensive project insurance for contractors, principals, and plant operators across the full asset lifecycle — from greenfield construction to ongoing operations.",
        policies: [
            { code: "CAR", name: "Contractor's All Risk (CAR)", description: "Comprehensive cover for civil construction projects — buildings, roads, bridges, dams, airports, tunnels. Section I: Material Damage to contract works (including materials at site, temporary works, construction plant on a limited basis). Section II: Third Party Liability (bodily injury & property damage to third parties). Section III: Surrounding Property (optional — existing structures that may be affected). Covers perils: fire, flood, earthquake, theft, faulty workmanship (consequential damage), design defect (resultant damage), testing of completed sections. Period: Commencement of work → Handing over + Maintenance/Defects Liability Period (12-24 months)." },
            { code: "EAR", name: "Erection All Risk (EAR)", description: "Covers mechanical/electrical equipment and machinery during the full installation lifecycle: Transit to site → Storage at site → Erection/assembly → Testing (cold & hot) → Commissioning → Trial runs. Section I: Material Damage (equipment, installation materials, construction machinery). Section II: Third Party Liability. Testing period (typically 4-12 weeks) is critical — most EAR claims occur here when equipment is first pushed to operational limits. Covers inland transit, storage at site, and the full erection phase." },
            { code: "MBD", name: "Machinery Breakdown (MBD)", description: "Covers sudden and unforeseen physical damage to installed, commissioned, and operational machinery from INTERNAL causes. Covered: electrical short circuit/overload/arc, mechanical failure/fracture, centrifugal force causing disintegration, defective material/casting (latent defects), operator error/negligence, water hammer, steam explosion, frost damage to cooling systems. NOT covered: gradual wear & tear, corrosion, erosion, cavitation, overhaul/maintenance costs, consequential losses (need separate MLOP policy). Machinery must have been successfully commissioned and in normal operation." },
            { code: "EEI", name: "Electronic Equipment Insurance (EEI)", description: "Specialized all-risks cover for electronic and computer systems: IT infrastructure (servers, storage, networking), medical equipment (MRI, CT, ultrasound, ventilators), telecom equipment (switches, towers, fiber), office equipment (PCs, printers, UPS). Covers: fire, theft, electrical surge/fluctuation, accidental damage, operator error, water damage, AC failure damage. Special sections: Data Media restoration costs, Increased Cost of Working (renting replacement equipment). Essential for IT companies, hospitals, banks, data centers, BPOs." },
            { code: "CPM", name: "Contractors Plant & Machinery (CPM)", description: "Covers the contractor's OWN construction equipment (not the project works — that's CAR). Includes: cranes, excavators, bulldozers, concrete mixers, generators, compressors, drilling rigs, piling equipment, welding sets, hoists. Covers physical loss/damage from: accident, fire, theft, collapse, overturning, flood, lightning. Covers equipment while working at site, idle at site, or in transit between sites. Separate from CAR which covers the project itself." },
            { code: "BPE", name: "Boiler & Pressure Plant Insurance", description: "Covers explosion or collapse of steam boilers, pressure vessels, economizers, and associated piping systems. Mandatory for boilers under Indian Boilers Act 1923. Covers: damage to the boiler/vessel itself, surrounding property damage, third-party liability from explosion. Includes annual inspection by competent person. Premium depends on capacity (kg/cm²), age, maintenance record." },
            { code: "ALOP", name: "Advance Loss of Profit (ALOP/DSU)", description: "Covers the PRINCIPAL's anticipated gross profit loss when a construction/erection project is delayed beyond planned completion date due to material damage under CAR/EAR. Also called DSU (Delay in Start-Up). Requirements: underlying CAR/EAR policy must be in place, delay must be caused by an insured peril, insured must declare anticipated annual revenue and select indemnity period. Indemnity starts from planned completion date, not from date of damage. Critical for power plants, manufacturing units, infrastructure projects." },
            { code: "MLOP", name: "Machinery Loss of Profits (MLOP/BIE)", description: "Covers loss of Gross Profit following machinery breakdown that interrupts production in an OPERATIONAL factory/plant. Requires underlying MBD policy — a valid material damage claim must trigger before MLOP activates. Covers: standing charges, profit loss, increased cost of working (alternative arrangements). Indemnity period: typically 6-12 months (time to repair/replace the machine). Does NOT cover the repair cost itself (that's MBD)." },
            { code: "DECENNIAL", name: "Decennial (Latent Defects) Insurance", description: "10-year structural guarantee cover for buildings — covers major structural defects that emerge after construction is complete and handed over. Covers: foundation failure, structural collapse, waterproofing failure (if structural), major settlement/subsidence. Common in Europe, increasingly used in India for large real estate/infrastructure projects. Single premium paid at project completion. Protects the building owner for 10 years post-handover." }
        ],
        addons: [
            { code: "CROSS-LIB", name: "Cross Liability (CAR/EAR)", description: "Treats each named insured (principal, contractor, sub-contractors) as if separately insured. If one insured party damages another's property or causes injury, the policy responds.", whoShouldTake: "Multi-party construction projects — principal + main contractor + sub-contractors all named on one policy. Essential for infrastructure projects, EPC contracts, and joint ventures.", whyItsNeeded: "On a joint policy, one insured cannot claim against another insured. If contractor damages principal's existing property, or sub-contractor injures main contractor's workers, the claim would be excluded without this.", claimImpact: "Without it: claims between co-insureds are excluded. If sub-contractor damages principal's existing building while working on the project — ZERO coverage. Parties must sue each other outside the policy." },
            { code: "MAINT", name: "Maintenance/Defects Liability Period", description: "Extends CAR/EAR cover beyond handing-over for 12-24 months. Covers damage arising from construction defects that manifest after completion, and damage caused while contractor returns for defect rectification.", whoShouldTake: "Project principals (owners) and contractors who remain responsible for defects after handover. Standard for all construction contracts with defects liability clauses.", whyItsNeeded: "Many construction defects only appear weeks/months after completion — waterproofing failure, structural settling, finishing defects. Without maintenance period extension, coverage ends at handover leaving these uninsured.", claimImpact: "Without it: any damage arising from a construction defect discovered AFTER handover is uninsured. If a wall collapses 3 months after completion due to faulty construction — no CAR coverage. Contractor bears cost personally." },
            { code: "SURR-PROP", name: "Surrounding Property Cover", description: "Section III of CAR/EAR — covers physical damage to EXISTING property in the vicinity of the project (neighboring buildings, roads, utilities, underground services).", whoShouldTake: "Any project in urban areas, near existing buildings, involving deep excavation, piling, demolition, vibration-intensive work, or dewatering that could affect adjacent structures.", whyItsNeeded: "Construction activities regularly damage neighboring properties — settlement from excavation, vibration cracking, dewatering causing subsidence. Standard CAR only covers the project works, not what's around them.", claimImpact: "Without it: damage to neighboring buildings, roads, underground utilities from your construction activity is EXCLUDED. If your piling causes cracks in the adjacent building — you have no insurance response. Full liability from own funds." },
            { code: "50-50", name: "50/50 Clause (Removal of Debris)", description: "Provides additional cover (typically 50% of claim amount) specifically for debris clearing costs. Standard CAR/EAR includes debris removal but only within the overall sum insured.", whoShouldTake: "Large construction projects, high-rise buildings, infrastructure projects, and any site where debris removal after a major loss (collapse, fire) would be extremely expensive.", whyItsNeeded: "After a major collapse or fire on a construction site, debris removal can cost 10-30% of the total loss. Standard policy includes it within SI — but this means less money available for actual reconstruction.", claimImpact: "Without it: debris removal costs reduce the amount available for repair/reconstruction. If debris clearing costs ₹1 Crore on a ₹5 Crore SI project, only ₹4 Crore remains for actual rebuilding — potentially insufficient." },
            { code: "OVERTIME", name: "Overtime, Night Work, Express Freight", description: "Covers additional costs of overtime labor, night work, working on holidays, and express freight charges to expedite repairs and minimize project delay after insured damage.", whoShouldTake: "Time-critical projects with penalties for delay (liquidated damages clauses), seasonal construction windows, and projects where delay costs far exceed the premium for expediting.", whyItsNeeded: "After insured damage, normal-pace repairs may delay the project by months — triggering LD penalties worth crores. Overtime and express freight dramatically cut delay but cost 1.5-3x normal rates.", claimImpact: "Without it: insurer only pays for repairs at normal working pace and cheapest transport. Overtime wages (1.5-2x), holiday working (2-3x), and express freight (5-10x sea freight) are entirely from own pocket — even though they save weeks of project delay." },
            { code: "AIR-FREIGHT", name: "Air Freight for Replacement Parts", description: "Covers the additional cost of air-freighting replacement parts/equipment when normal surface transport would cause unacceptable project delay. Standard policy only reimburses cheapest mode.", whoShouldTake: "Projects using imported equipment (turbines, generators, specialized components) where replacement parts are manufactured overseas and sea freight takes 4-8 weeks.", whyItsNeeded: "When a critical imported component is damaged, sea freight replacement takes 6-8 weeks. Air freight gets it in 3-5 days but costs 10-20x more. Without this add-on, you choose between paying the freight difference yourself or accepting months of delay.", claimImpact: "Without it: insurer reimburses only cheapest transport (sea freight ₹2 Lakhs). If you air-freight the part for ₹25 Lakhs to save 6 weeks of project delay — you bear ₹23 Lakhs difference. Meanwhile, each week of delay may cost ₹50 Lakhs in LD penalties." },
            { code: "ESCL-CAR", name: "Escalation Clause (CAR/EAR)", description: "Automatically increases the sum insured during the project (10-20% per annum) to cover cost escalation from inflation, material price increases, and wage hikes.", whoShouldTake: "Long-duration projects (2+ years) where material costs and labor rates will certainly increase during execution. Infrastructure projects, large industrial plants, and highway/railway construction.", whyItsNeeded: "A 3-year project's costs can escalate 30-40% from start to finish. Without escalation, the sum insured set at project start becomes inadequate by year 3 — triggering underinsurance and proportionate claim reduction.", claimImpact: "Without it: if project costs escalate 25% over 2 years but SI remains unchanged, you are 25% underinsured. A ₹10 Crore loss would only pay ₹7.5 Crore (average clause applies). The ₹2.5 Crore shortfall is from own funds." },
            { code: "OFFSITE", name: "Offsite Storage Cover", description: "Extends CAR/EAR cover to materials and equipment stored at locations other than the declared project site — warehouses, fabrication yards, ports, marshalling areas.", whoShouldTake: "Large projects with prefabricated components, imported equipment stored at ports/CFS, structural steel fabricated offsite, or materials stored in multiple warehouses before delivery to site.", whyItsNeeded: "Standard CAR/EAR only covers materials AT the project site. But project materials are often stored offsite for weeks/months — at ports (awaiting customs), fabrication yards, or overflow warehouses.", claimImpact: "Without it: materials stored anywhere other than the declared project site have ZERO coverage. If ₹2 Crore of imported equipment sitting at the port warehouse is damaged by fire — no claim. It wasn't 'at site'." },
            { code: "DEFECTIVE-PART", name: "LEG 2 — Cost of Replacement of Defective Part", description: "Standard CAR/EAR (LEG 1) only covers damage CAUSED BY the defect, not the defective item itself. LEG 2 extends to cover the cost of replacing/repairing the defective part or material that caused the damage.", whoShouldTake: "Projects using high-value specialized components where a single defective part can cause extensive damage — power plants, chemical process equipment, structural steel, turbines, generators.", whyItsNeeded: "Under standard cover, if a defective bearing causes a turbine to collapse, the policy pays for the turbine damage but NOT the bearing that caused it. LEG 2 pays for the defective bearing too.", claimImpact: "Without it (LEG 1 only): insurer pays for consequential damage but NOT the defective item itself. If a ₹50 Lakh defective weld causes ₹5 Crore in structural collapse — policy pays ₹5 Crore damage but NOT the ₹50 Lakh cost of replacing the defective weld." },
            { code: "DEFECTIVE-DESIGN", name: "LEG 3 — Defective Design Cover", description: "Most extensive engineering cover — includes cost of improving/correcting a defective DESIGN to prevent recurrence of the damage. Goes beyond LEG 2 (defective part) to cover the intellectual redesign cost.", whoShouldTake: "Only for well-established, proven construction methods with reputable contractors and designers. Not available for experimental or first-of-kind designs. Primarily for large infrastructure and industrial projects.", whyItsNeeded: "If a design flaw causes damage, you need to not only repair the damage but also fix the design so it doesn't happen again. LEG 3 covers the cost of redesigning — engineering fees, design changes, structural modifications to improve the failed design.", claimImpact: "Without it: cost of redesign and design improvement is excluded. After a design-caused collapse, insurer pays repair costs but NOT the fees to redesign the structure. You must fund the design improvement yourself — or risk the same failure recurring." },
            { code: "PRINCIPAL-SUPPLY", name: "Principal Supplied Materials", description: "Covers materials and equipment supplied by the project owner (principal) to the contractor for incorporation in the works. Standard policy assumes contractor supplies everything.", whoShouldTake: "Project owners who supply key equipment to contractors — common in power plants (owner supplies turbines), industrial projects (owner procures specialized machinery), and government projects (department-supplied materials).", whyItsNeeded: "Many contracts involve owner-supplied materials (free-issue materials). Standard CAR/EAR covers contractor-owned items. Without this extension, the principal's materials have no coverage under the construction policy.", claimImpact: "Without it: owner-supplied equipment and materials at the construction site have ZERO coverage under the CAR/EAR policy. If the ₹10 Crore turbine (supplied by the owner) is damaged during erection — no claim under the project policy." },
            { code: "TESTING-EXT", name: "Extended Testing Period", description: "Extends the standard 4-week testing period in EAR policies to 8-12 weeks or more for complex equipment requiring extended commissioning.", whoShouldTake: "Power plants, chemical processing units, refineries, cement plants, complex manufacturing lines — any project where equipment commissioning realistically takes longer than the standard 4 weeks.", whyItsNeeded: "Standard EAR allows 4 weeks for testing. But complex equipment (gas turbines, chemical reactors, continuous process lines) needs 8-12+ weeks of testing, load trials, and performance guarantees. Without extension, equipment is uninsured after week 4.", claimImpact: "Without it: coverage ends 4 weeks after testing begins. If your gas turbine suffers a catastrophic failure in week 6 of commissioning — outside the standard testing period, but not yet handed over — ZERO coverage. A gap of potentially ₹50+ Crore." },
            { code: "MBD-ADDL-EXP", name: "Additional Expenses (MBD)", description: "Covers extra costs incurred to expedite repair/replacement of broken-down machinery — overtime labor, express transport of spare parts, temporary equipment hire, and night work charges.", whoShouldTake: "Manufacturing plants where machine downtime costs exceed repair costs, continuous process industries (cement, steel, chemicals), and seasonal businesses where every day of downtime means lost revenue.", whyItsNeeded: "Normal repair timelines for heavy machinery: 4-12 weeks. But production downtime may cost ₹10-50 Lakhs/day. Paying overtime and air-freighting parts can cut repair from 8 weeks to 2 weeks — but standard MBD only pays normal-cost repair.", claimImpact: "Without it: only normal-pace repair costs are covered. If you spend ₹20 Lakhs on overtime + air freight to cut downtime from 8 weeks to 2 weeks (saving ₹3 Crore in lost production) — you bear that ₹20 Lakhs. Insurer pays only standard repair cost." },
            { code: "MBD-FOUND", name: "Foundations Cover (MBD)", description: "Extends MBD coverage to include foundations, masonry, brickwork, and supports of the insured machinery. Standard MBD covers only the machine itself, not its base or supporting structure.", whoShouldTake: "Heavy machinery with substantial foundations — turbines, generators, large presses, rolling mills, centrifuges, hammer forges — where foundation damage from vibration or machine failure is possible.", whyItsNeeded: "When heavy machinery breaks down catastrophically (centrifugal disintegration, seizure), the vibration and impact often damages the concrete foundation. Standard MBD pays for the machine but not the ₹20-50 Lakh foundation repair.", claimImpact: "Without it: machine repair is covered but foundation damage is excluded. If a turbine failure cracks its ₹30 Lakh reinforced concrete foundation — policy pays for the turbine, but the foundation repair comes from own funds." },
            { code: "EEI-DATA", name: "Data Media & Programs (EEI)", description: "Covers cost of restoring/reconstituting data, software programs, and operating systems on damaged electronic media. Includes data recovery specialists, software reinstallation, and reconstruction of records.", whoShouldTake: "IT companies, data centers, hospitals (patient records), banks (transaction data), any business where data on electronic equipment is more valuable than the hardware itself.", whyItsNeeded: "A server worth ₹10 Lakhs may contain data worth ₹10 Crore. Standard EEI covers the physical hardware but the cost of data recovery, software reinstallation, and record reconstruction needs this specific extension.", claimImpact: "Without it: hardware replacement is covered but data recovery/restoration costs are excluded. If a ₹10 Lakh server is damaged and data recovery costs ₹5 Lakhs + software reinstallation costs ₹3 Lakhs — you bear ₹8 Lakhs on top of the claim." },
            { code: "EEI-ICOW", name: "Increased Cost of Working (EEI)", description: "Covers additional operational expenses when insured electronic equipment breaks down — renting replacement servers, using cloud/external processing facilities, temporary equipment hire to maintain operations.", whoShouldTake: "Businesses dependent on IT systems for daily operations — IT services companies, BPOs, e-commerce platforms, hospitals, banks, trading firms where even 1 day of IT downtime means massive revenue loss.", whyItsNeeded: "When your server/core system fails, you need immediate alternatives — renting servers, moving to cloud, temporary equipment. These emergency expenses maintain your business but are over and above the repair cost.", claimImpact: "Without it: costs of renting temporary replacement equipment, using external processing services, or emergency cloud migration are all from own pocket. Standard EEI covers repair/replacement of the damaged equipment but not the business continuity cost during repair." },
            { code: "OWNERS-SURROUNDING", name: "Owner's Surrounding Property (MBD)", description: "Extends MBD coverage to damage caused by the machinery breakdown to OTHER property of the insured — adjacent machines, buildings, raw materials, or finished goods damaged by the breakdown event.", whoShouldTake: "Manufacturing plants with closely-spaced machinery, process industries where one machine failure can damage adjacent equipment or stock, and facilities where machines are interconnected.", whyItsNeeded: "When a machine breaks down violently (explosion, centrifugal disintegration, oil spray), it often damages adjacent machines, walls, stock, and wiring. Standard MBD only covers the broken machine — not the collateral damage.", claimImpact: "Without it: only the broken machine is covered. Adjacent machines damaged by flying debris, stock contaminated by leaking oil, walls cracked by vibration — all excluded from the MBD claim. You bear the entire collateral damage cost." },
            { code: "EXPEDITING", name: "Expediting Expenses (General)", description: "Covers costs of overtime, express freight, temporary repairs, and premium charges to speed up replacement/repair of damaged works. Applied across CAR/EAR/MBD to reduce project delay.", whoShouldTake: "All engineering policyholders where time is critical — projects with LD clauses, seasonal work windows, or operations where downtime cost vastly exceeds the premium for expediting.", whyItsNeeded: "Across all engineering classes, the cost of delay often dwarfs the repair cost. Expediting expenses (overtime, express parts, temporary measures) can save weeks of delay and avoid liquidated damages far exceeding the extra cost.", claimImpact: "Without it: all costs above normal-pace repair are excluded. Express freight, overtime wages, weekend/holiday working, temporary repairs while awaiting permanent parts — all from own funds. Project delay penalty accrues daily while you wait for normal-speed repair." }
        ]
    }
};

