// ===== INSURANCE TAB CONTENT =====
const insuranceTabContent = {
    marine: {
        title: "Marine Insurance Clauses",
        desc: "Institute Cargo Clauses (ICC) for international transit and Institute Trade Clauses (ITC) for inland domestic transit.",
        cards: [
            { title: "ICC (A) — All Risks", content: `<p>The broadest marine coverage. Covers ALL risks of loss or damage except specific exclusions.</p><h4>Risks Covered:</h4><ul><li>Fire, explosion, lightning</li><li>Vessel sinking, capsizing, grounding, stranding</li><li>Collision of vessel or craft with any external object</li><li>Overturning or derailment of land conveyance</li><li>Earthquake, volcanic eruption</li><li>Washing overboard, jettison</li><li>Entry of sea/lake/river water into vessel or container</li><li><strong>Theft, pilferage, non-delivery</strong></li><li><strong>Breakage, leakage, wetting, contamination</strong></li><li><strong>Hook damage, denting, scratching</strong></li><li><strong>Fresh/rain water damage</strong></li><li>General average and salvage charges</li></ul><h4>Exclusions:</h4><ul><li>Wilful misconduct of the insured</li><li>Ordinary leakage, wear and tear</li><li>Insufficiency of packing</li><li>Inherent vice of goods</li><li>Delay</li><li>War, strikes (separate cover available)</li></ul><div class="ins-highlight">Mandatory under CIP Incoterm. Recommended for high-value goods, electronics, fragile items.</div>` },
            { title: "ICC (B) — Named Perils", content: `<p>Intermediate coverage. Only specifically listed perils are covered.</p><h4>Risks Covered:</h4><ul><li>Fire or explosion</li><li>Vessel stranding, grounding, sinking, capsizing</li><li>Overturning or derailment of land conveyance</li><li>Collision with external object (not water)</li><li>Discharge of cargo at port of distress</li><li>Earthquake, volcanic eruption, lightning</li><li>Washing overboard</li><li>Entry of sea/lake/river water into vessel</li><li>Total loss of package during loading/unloading</li><li>General average and jettison</li></ul><h4>NOT Covered:</h4><ul><li>Theft, pilferage, non-delivery</li><li>Rain/fresh water damage</li><li>Breakage, denting, scratching</li><li>Wetting by sweat/condensation</li><li>Contamination, hook damage</li></ul><div class="ins-highlight">Suitable for raw materials, steel, timber — goods not easily stolen or damaged by water.</div>` },
            { title: "ICC (C) — Major Perils Only", content: `<p>Narrowest coverage. Only catastrophic marine events covered.</p><h4>Risks Covered:</h4><ul><li>Fire or explosion</li><li>Vessel stranding, grounding, sinking, capsizing</li><li>Overturning or derailment of land conveyance</li><li>Collision with external object (not water)</li><li>Discharge at port of distress</li><li>General average sacrifice and jettison</li></ul><h4>NOT Covered:</h4><ul><li>Earthquake, volcanic eruption, lightning</li><li>Washing overboard</li><li>Entry of sea water into vessel</li><li>Theft, breakage, wetting, contamination</li><li>Loading/unloading losses</li></ul><div class="ins-highlight">Minimum level required under CIF. Used for low-value bulk cargo (coal, ore, grains).</div>` },
            { title: "ITC (A) — Inland All Risks", content: `<p>Comprehensive coverage for goods in domestic transit by road, rail, or inland waterway.</p><h4>Risks Covered:</h4><ul><li>All risks of physical loss or damage from external causes</li><li>Road accidents — collision, overturning, jackknifing</li><li>Fire and explosion</li><li>Theft of entire consignment or pilferage</li><li>Water damage — rain, flood, river overflow</li><li>Breakage, denting, scratching during handling</li><li>Loading and unloading damage</li><li>Bridge collapse, landslide, derailment</li><li>Non-delivery of entire package</li></ul><h4>Exclusions:</h4><ul><li>Wear and tear, gradual deterioration</li><li>Inherent vice (natural spoilage)</li><li>Insufficient packing</li><li>Delay, loss of market</li></ul><div class="ins-highlight">Recommended for ALL Indian inland movements. Essential given road conditions, theft risk, and monsoon flooding.</div>` },
            { title: "ITC (B) & ITC (C) — Limited Inland", content: `<p><strong>ITC (B)</strong> covers named perils: fire, overturning, collision, flood, storm, cyclone, earthquake, landslide, bridge collapse. Does NOT cover theft, breakage, or rain damage.</p><p><strong>ITC (C)</strong> is bare minimum: only fire, overturning, and collision of carrying vehicle. Does NOT cover natural disasters, theft, water damage, or loading damage.</p><div class="ins-highlight">ITC (B): Acceptable for resilient goods on safe routes. ITC (C): Only for very low-value bulk cargo. In India, ITC (A) is strongly recommended due to road conditions and weather risks.</div>` }
        ]
    },
    fire: {
        title: "Fire Insurance Clauses",
        desc: "Standard Fire & Special Perils Policy (SFSP) and its add-on covers for comprehensive property protection.",
        cards: [
            { title: "Standard Fire & Special Perils Policy (SFSP)", content: `<p>The foundational property insurance policy in India covering buildings, machinery, stock, and contents.</p><h4>Perils Covered:</h4><ul><li>Fire (accidental) and Lightning</li><li>Explosion / Implosion</li><li>Aircraft damage (falling objects)</li><li>Riot, Strike, Malicious Damage (RSMD)</li><li>Storm, Tempest, Flood, Inundation (STFI)</li><li>Impact damage (vehicles, animals)</li><li>Subsidence, Landslide, Rockslide</li><li>Bursting/overflowing of water tanks, pipes</li><li>Missile testing operations</li><li>Leakage from automatic sprinkler installations</li><li>Bush fire</li></ul><h4>Exclusions:</h4><ul><li>War and nuclear perils</li><li>Pollution and contamination</li><li>Electrical/mechanical breakdown</li><li>Willful destruction</li><li>Loss of earnings (unless BI cover added)</li></ul><div class="ins-highlight">Most widely used property policy in India. Can be on Market Value or Reinstatement Value basis.</div>` },
            { title: "Reinstatement Value & Average Clause", content: `<p><strong>Reinstatement Value:</strong> Covers full replacement/rebuilding cost without any depreciation deduction. Premium is higher but payout is complete.</p><p><strong>Average Clause:</strong> If sum insured is less than actual property value, claims are reduced proportionately.</p><h4>Average Clause Formula:</h4><ul><li><strong>Claim = (Sum Insured ÷ Actual Value) × Loss Amount</strong></li><li>Example: Property worth ₹2Cr, insured for ₹1Cr → claim of ₹40L becomes ₹20L (50%)</li></ul><h4>How to Avoid Average:</h4><ul><li>Regular professional valuations</li><li>Index-linked sum insured</li><li>Day-1 Reinstatement basis (85% threshold)</li><li>Agreed Value policy (pre-agreed valuation)</li></ul><div class="ins-highlight">Critical: Underinsurance is the #1 reason for reduced claim payouts in India. Always ensure adequate sum insured.</div>` },
            { title: "Earthquake Cover", content: `<p>Optional add-on to SFSP covering damage from seismic activity.</p><h4>Two Variants:</h4><ul><li><strong>Fire & Shock:</strong> Covers fire following earthquake + structural damage from seismic shock (wider)</li><li><strong>Fire Only:</strong> Covers only fire resulting from earthquake (narrower)</li></ul><h4>Rating by Seismic Zone:</h4><ul><li>Zone II — Low risk (lowest premium)</li><li>Zone III — Moderate risk</li><li>Zone IV — High risk (higher premium)</li><li>Zone V — Very high risk (highest premium)</li></ul><div class="ins-highlight">Cities like Delhi (Zone IV), Guwahati (Zone V), Mumbai (Zone III) have varying earthquake premiums. Fire & Shock variant is recommended.</div>` },
            { title: "STFI & Terrorism Cover", content: `<p><strong>STFI (Storm, Tempest, Flood, Inundation):</strong> Usually included in SFSP. Covers damage from cyclones, hurricanes, floods. Excess/deductible typically 1-5%.</p><p><strong>Terrorism Cover:</strong> Provided through the Indian Market Terrorism Risk Insurance Pool backed by GIC Re.</p><h4>Terrorism Cover Details:</h4><ul><li>Covers property damage from declared acts of terrorism</li><li>Also covers Business Interruption (if underlying BI exists)</li><li>Managed by Indian Market Terrorism Pool</li><li>GIC Re provides reinsurance capacity</li><li>Premium based on sum insured and location risk</li></ul><div class="ins-highlight">Post-26/11, terrorism cover became essential for all major commercial and industrial risks in India. The Pool ensures availability across all locations.</div>` },
            { title: "Business Interruption (Fire BI)", content: `<p>Covers loss of Gross Profit due to business interruption following fire or allied perils damage.</p><h4>Key Elements:</h4><ul><li><strong>Indemnity Period:</strong> 12 / 18 / 24 / 36 months (maximum recovery period)</li><li><strong>Gross Profit:</strong> Turnover minus variable costs (purchases, packing)</li><li><strong>Increased Cost of Working:</strong> Extra expenses to maintain turnover</li><li><strong>Trigger:</strong> Must have valid material damage claim under SFSP</li></ul><h4>Important Conditions:</h4><ul><li>Sum insured = Gross Profit × Indemnity Period ratio</li><li>Underinsurance attracts Average Clause (same as material damage)</li><li>Insured must mitigate loss — take reasonable steps to resume operations</li></ul><div class="ins-highlight">BI loss often exceeds material damage loss. A factory fire causing ₹1Cr property damage may cause ₹5Cr+ in lost profits during rebuilding.</div>` }
        ]
    },
    engineering: {
        title: "Engineering Insurance Clauses",
        desc: "Construction risks, machinery breakdown, and project insurance covering the full lifecycle from building to operation.",
        cards: [
            { title: "Contractor's All Risk (CAR)", content: `<p>Comprehensive cover for civil construction projects — buildings, roads, bridges, dams, airports.</p><h4>Three Sections:</h4><ul><li><strong>Section I — Material Damage:</strong> Covers physical loss/damage to contract works, materials at site, construction plant</li><li><strong>Section II — Third Party Liability:</strong> Bodily injury or property damage to third parties</li><li><strong>Section III — Surrounding Property (Optional):</strong> Existing structures near the project</li></ul><h4>Coverage Period:</h4><ul><li>From commencement of work</li><li>Through construction phase</li><li>Until handing over to principal</li><li>+ Maintenance/Defects Liability Period (typically 12-24 months)</li></ul><h4>Perils Covered:</h4><ul><li>Fire, lightning, explosion</li><li>Storm, flood, earthquake, landslide</li><li>Theft and burglary</li><li>Faulty workmanship (resulting damage, not cost of redo)</li><li>Collapse, subsidence</li><li>Human error, negligence</li></ul><div class="ins-highlight">CAR covers the project value + materials + labor. Most claims occur during monsoon season and excavation phase in India.</div>` },
            { title: "Erection All Risk (EAR)", content: `<p>Covers mechanical and electrical equipment during transport to site, storage, erection, testing, and commissioning.</p><h4>Coverage Phases:</h4><ul><li><strong>Transit:</strong> From supplier to project site</li><li><strong>Storage:</strong> At site before installation</li><li><strong>Erection:</strong> During installation and assembly</li><li><strong>Testing:</strong> Cold and hot testing (4-12 weeks typically)</li><li><strong>Commissioning:</strong> Trial runs and performance tests</li></ul><h4>Key Difference from CAR:</h4><ul><li>CAR = Civil works (concrete, steel structures)</li><li>EAR = Mechanical/electrical installation (turbines, generators, pipelines)</li><li>Many projects need BOTH</li></ul><div class="ins-highlight">Testing & commissioning period (4-12 weeks) is when most EAR claims occur — equipment is pushed to its operational limits for the first time.</div>` },
            { title: "Machinery Breakdown (MBD)", content: `<p>Covers sudden and unforeseen physical damage to installed, operational machinery from internal causes.</p><h4>Covered Causes:</h4><ul><li>Electrical short circuit, overload, power surge</li><li>Mechanical failure, fracture of parts</li><li>Centrifugal force causing disintegration</li><li>Defective material or casting (latent defects)</li><li>Operator error or negligence</li><li>Water hammer, steam explosion</li></ul><h4>NOT Covered:</h4><ul><li>Gradual wear and tear, corrosion, erosion</li><li>Routine maintenance costs</li><li>Overhaul and periodic replacement</li><li>Aesthetic damage (scratches without functional impact)</li><li>Machinery under construction or testing (use EAR)</li></ul><div class="ins-highlight">Critical requirement: Machine must have been SUCCESSFULLY commissioned and in normal operation. MBD only covers SUDDEN failures — gradual deterioration is excluded.</div>` },
            { title: "Electronic Equipment Insurance (EEI)", content: `<p>Specialized cover for computers, servers, medical equipment, telecom gear, and other electronic systems.</p><h4>Covered:</h4><ul><li>Fire, explosion, lightning (including power surge)</li><li>Short circuit, electrical disturbance</li><li>Theft and burglary</li><li>Accidental damage (dropping, collision)</li><li>Water damage (leakage, flooding)</li><li>Operator error</li><li><strong>Data Media:</strong> Cost of restoring data on damaged media</li><li><strong>Increased Working Cost:</strong> Renting replacement equipment</li></ul><h4>NOT Covered:</h4><ul><li>Wear and tear, gradual deterioration</li><li>Aesthetic damage</li><li>Software errors (unless causing physical damage)</li><li>Consequential losses (unless BI extension purchased)</li></ul><div class="ins-highlight">Essential for IT companies, hospitals (MRI/CT machines), banks (ATMs/servers), and data centers. Always maintain proper UPS and environmental controls.</div>` },
            { title: "ALOP / DSU — Delay in Start-Up", content: `<p>Covers the principal's anticipated profit loss when a construction project is delayed due to insured damage under CAR/EAR.</p><h4>How It Works:</h4><ul><li>Project planned completion: January 1</li><li>Insured damage (fire/flood) causes 3-month delay</li><li>Actual completion: April 1</li><li>ALOP covers: 3 months of lost gross profit</li></ul><h4>Key Requirements:</h4><ul><li>Must have underlying CAR or EAR policy</li><li>Delay must be caused by insured peril</li><li>Indemnity period starts from planned completion date</li><li>Insured must declare anticipated annual revenue</li></ul><div class="ins-highlight">Also called DSU (Delay in Start-Up). The insured amount should reflect the gross profit expected in the first year of operations multiplied by the indemnity period ratio.</div>` }
        ]
    },
    liability: {
        title: "Liability Insurance Clauses",
        desc: "Legal liability covers protecting businesses and individuals against third-party claims for bodily injury, property damage, and financial loss.",
        cards: [
            { title: "Public Liability Insurance", content: `<p>Covers legal liability for bodily injury or property damage to third parties arising from business operations or premises.</p><h4>Scope:</h4><ul><li>Bodily injury to visitors, passersby, neighboring property occupants</li><li>Property damage caused by business activities</li><li>Pollution liability (sudden and accidental)</li><li>Food/beverage liability for hospitality businesses</li></ul><h4>Indian Context:</h4><ul><li><strong>Public Liability Insurance Act 1991:</strong> Mandatory for industries handling hazardous substances</li><li>Covers compensation to victims of industrial accidents</li><li>Environment Relief Fund contribution required</li></ul><h4>Trigger:</h4><ul><li><strong>Occurrence basis:</strong> Covers incidents occurring during policy period regardless of when claim is made</li></ul><div class="ins-highlight">Mandatory for: Chemical plants, petroleum storage, manufacturing with hazardous materials. Penalty for non-compliance under the Act.</div>` },
            { title: "Directors & Officers Liability (D&O)", content: `<p>Protects directors and senior officers against personal liability for wrongful acts in their managerial capacity.</p><h4>Coverage:</h4><ul><li>Shareholder derivative actions and class actions</li><li>Regulatory investigations (SEBI, RBI, MCA)</li><li>Employment practices liability (wrongful termination)</li><li>Breach of fiduciary duty allegations</li><li>Insolvency-related claims</li><li>Securities law violations</li></ul><h4>Policy Structure:</h4><ul><li><strong>Side A:</strong> Covers directors when company cannot indemnify (insolvency)</li><li><strong>Side B:</strong> Reimburses company for indemnifying directors</li><li><strong>Side C:</strong> Covers the company itself for securities claims</li></ul><h4>Trigger:</h4><ul><li><strong>Claims-made basis</strong> with retroactive date</li><li>Defense costs typically WITHIN limit (erodes available indemnity)</li></ul><div class="ins-highlight">Critical for listed companies, startups with investors, and any company with independent directors. SEBI regulations increase D&O exposure significantly.</div>` },
            { title: "Commercial General Liability (CGL)", content: `<p>The broadest liability coverage — covers bodily injury, property damage, and personal/advertising injury.</p><h4>Coverage Parts:</h4><ul><li><strong>Premises Liability:</strong> Injuries on your property (slip & fall)</li><li><strong>Operations Liability:</strong> Damage caused by your work at other locations</li><li><strong>Products Liability:</strong> Injury from products after sale</li><li><strong>Completed Operations:</strong> Damage from work already finished</li><li><strong>Personal Injury:</strong> Defamation, false arrest, malicious prosecution</li><li><strong>Advertising Injury:</strong> Copyright infringement, misleading advertising</li></ul><h4>Limits Structure:</h4><ul><li>Per Occurrence limit + Annual Aggregate limit</li><li>Defense costs: typically IN ADDITION to limit (doesn't reduce payout)</li></ul><div class="ins-highlight">CGL is the go-to liability policy for businesses. Unlike Public Liability, it covers products, completed operations, and advertising injury. Most comprehensive general cover available.</div>` },
            { title: "Product Liability", content: `<p>Covers legal liability for bodily injury or property damage caused by defective products manufactured, sold, or distributed.</p><h4>Consumer Protection Act 2019 (India):</h4><ul><li><strong>Strict liability:</strong> No need to prove negligence — defect is enough</li><li>Applies to: Manufacturers, sellers, and service providers</li><li>Compensation for: Death, injury, property damage, mental anguish</li><li>Product recall costs: Usually separate sub-limit or separate policy</li></ul><h4>Types of Defects:</h4><ul><li><strong>Manufacturing defect:</strong> Error in production process</li><li><strong>Design defect:</strong> Inherently unsafe design</li><li><strong>Warning defect:</strong> Inadequate instructions or warnings</li></ul><div class="ins-highlight">Critical for: Pharma companies, food manufacturers, auto parts suppliers, electronics makers, and exporters to USA/EU where product liability litigation is aggressive.</div>` },
            { title: "Cyber Liability Insurance", content: `<p>Covers data breach costs, cyber extortion, network interruption, and regulatory penalties from cyber incidents.</p><h4>First-Party Covers (Own Loss):</h4><ul><li>Breach response costs (forensics, notification, credit monitoring)</li><li>Data restoration expenses</li><li>Business interruption from network outage</li><li>Cyber extortion / ransomware payments</li><li>Reputation management / PR costs</li></ul><h4>Third-Party Covers (Liability to Others):</h4><ul><li>Claims from affected data subjects</li><li>Regulatory fines and penalties (DPDP Act 2023)</li><li>Payment Card Industry (PCI) fines</li><li>Media liability (website content)</li></ul><h4>DPDP Act 2023 Impact:</h4><ul><li>72-hour breach notification mandatory</li><li>Penalties up to ₹250 Crore</li><li>Data fiduciaries must implement safeguards</li></ul><div class="ins-highlight">No longer optional for any business handling customer data. DPDP Act enforcement makes cyber insurance critical for IT, BFSI, healthcare, and e-commerce sectors.</div>` }
        ]
    }
};
